using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidateActualMudDrive {
public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var source=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var sourceBody=source.GetComponent<Rigidbody>();bool kinematic=sourceBody.isKinematic;var velocity=sourceBody.linearVelocity;var angular=sourceBody.angularVelocity;var mode=Physics.simulationMode;bool paused=EditorApplication.isPaused;GameObject clone=null,probe=null;try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;sourceBody.isKinematic=true;var soils=UnityEngine.Object.FindObjectsByType<SoftGroundRuts>().Where(s=>s.enabled&&s.profile!=null&&s.persistentId!=null&&s.persistentId.StartsWith("main0")).ToArray();if(soils.Length==0)throw new Exception("No main authored mud");var root=soils[0].transform.parent;var entry=root.position-root.forward*2;RaycastHit best=default;bool found=false;foreach(var soil in soils)if(soil.GetComponent<MeshCollider>().Raycast(new Ray(entry+Vector3.up*10,Vector3.down),out var hit,20)&&(!found||hit.point.y>best.point.y)){best=hit;found=true;}if(!found)throw new Exception("No entry surface");clone=UnityEngine.Object.Instantiate(source.gameObject,best.point+Vector3.up*.65f,Quaternion.LookRotation(root.forward));var v=clone.GetComponent<VehiclePhysics>();var rb=clone.GetComponent<Rigidbody>();rb.isKinematic=false;v.automaticSimulation=false;v.externalControl=true;clone.GetComponent<VehiclePlayerInput>().enabled=false;clone.GetComponent<VehicleAudio>().enabled=false;v.Initialize();v.SetFourWheelDrive(true);v.SetTransmission(false,true);v.SetInput(new VehicleControlInput{brake=1});Physics.SyncTransforms();Action step=()=>{v.Simulate(.01f);Physics.Simulate(.01f);v.SendMessage("LateUpdate");};for(int i=0;i<200;i++)step();var start=rb.position;v.SetInput(new VehicleControlInput{throttle=1});float peakSpeed=0;float spin=0,depthBefore=soils.Max(s=>s.DugDepth);int mud=0;for(int i=0;i<900;i++){step();peakSpeed=Mathf.Max(peakSpeed,rb.linearVelocity.magnitude);spin=Mathf.Max(spin,v.WheelspinSpeed);mud=Mathf.Max(mud,v.MudContacts);}foreach(var soil in soils)soil.Commit();float depth=soils.Max(s=>s.DugDepth),travel=Vector3.Dot(rb.position-start,root.forward);if(peakSpeed>25||mud<2||spin<2||depth<.025f||v.Wheels.Count(w=>w.isGrounded)<2&&!(soils.Any(s=>s.GetComponent<MudRoadSection>()!=null&&s.GetComponent<MudRoadSection>().profile.fullWidthFurrows)&&Mathf.Abs(travel)<.2f&&Mathf.Abs(rb.linearVelocity.y)<.2f&&depth>.12f))throw new Exception("Actual drive failed mud="+mud+" peakSpeed="+peakSpeed+" spin="+spin+" rut="+depth+" travel="+travel+" pos="+rb.position);int tested=0;float maxMismatch=0;foreach(var soil in soils){probe=new GameObject("TEMP visible mud probe");probe.transform.SetPositionAndRotation(soil.transform.position,soil.transform.rotation);probe.transform.localScale=soil.transform.lossyScale;var collider=probe.AddComponent<MeshCollider>();collider.sharedMesh=soil.GetComponent<MeshFilter>().sharedMesh;var bounds=soil.GetComponent<Renderer>().bounds;for(int z=0;z<9;z++)for(int x=0;x<9;x++){var p=new Vector3(Mathf.Lerp(bounds.min.x,bounds.max.x,(x+.5f)/9),bounds.max.y+2,Mathf.Lerp(bounds.min.z,bounds.max.z,(z+.5f)/9));var ray=new Ray(p,Vector3.down);if(collider.Raycast(ray,out var visual,10)&&soil.GetComponent<MeshCollider>().Raycast(ray,out var physical,10)){maxMismatch=Mathf.Max(maxMismatch,Mathf.Abs(visual.point.y-physical.point.y));tested++;}}UnityEngine.Object.DestroyImmediate(probe);probe=null;}if(tested<20||maxMismatch>.003f)throw new Exception("Actual mesh/collider mismatch "+maxMismatch+" rays="+tested);var digRay=new Ray(root.position+root.right*.7f+Vector3.up*10,Vector3.down);RaycastHit before=default;bool digFound=false;foreach(var soil in soils)if(soil.GetComponent<MeshCollider>().Raycast(digRay,out var hit,20)&&(!digFound||hit.point.y>before.point.y)){before=hit;digFound=true;}if(!digFound)throw new Exception("No deep rut probe");float existingDepth=before.collider.GetComponent<SoftGroundRuts>().DepthAt(before.point);for(int i=0;i<700;i++){SoftGroundRuts.Contact(before.point,root.forward,.285f,6000,16,1,.01f);SoftGroundRuts.AdvanceAll(.01f);}foreach(var soil in soils)soil.Commit();float actualTop=float.MinValue,visibleTop=float.MinValue;foreach(var hit in Physics.RaycastAll(digRay,20,~0,QueryTriggerInteraction.Ignore))if(hit.normal.y>.3f&&hit.point.y<=before.point.y+.1f&&!hit.collider.transform.IsChildOf(source.transform)&&!hit.collider.transform.IsChildOf(clone.transform))actualTop=Mathf.Max(actualTop,hit.point.y);foreach(var soil in soils){probe=new GameObject("TEMP deep render probe");probe.transform.SetPositionAndRotation(soil.transform.position,soil.transform.rotation);probe.transform.localScale=soil.transform.lossyScale;var c=probe.AddComponent<MeshCollider>();c.sharedMesh=soil.GetComponent<MeshFilter>().sharedMesh;if(c.Raycast(digRay,out var hit,20))visibleTop=Mathf.Max(visibleTop,hit.point.y);UnityEngine.Object.DestroyImmediate(probe);probe=null;}float actualDrop=before.point.y-actualTop;if(actualDrop+existingDepth<.12f||Mathf.Abs(actualTop-visibleTop)>.003f)throw new Exception("Underlying invisible support: existing="+existingDepth+" drop="+actualDrop+" gap="+(actualTop-visibleTop));return "PASS supplied original forest mud drive: contacts="+mud+", slip="+spin.ToString("F1")+"m/s, 9s travel="+travel.ToString("F2")+"m, retained rut="+depth.ToString("F3")+"m; independent visible-mesh rays="+tested+", max collision difference="+maxMismatch.ToString("F5")+"m; deep rut global collision drop="+(actualDrop+existingDepth).ToString("F3")+"m with no invisible underlay.";}finally{if(clone!=null)UnityEngine.Object.DestroyImmediate(clone);if(probe!=null)UnityEngine.Object.DestroyImmediate(probe);sourceBody.isKinematic=kinematic;if(!kinematic){sourceBody.linearVelocity=velocity;sourceBody.angularVelocity=angular;}Physics.simulationMode=mode;EditorApplication.isPaused=paused;}}
}
